INSERT INTO scenario_attempt (
    profile_id, scenario_id, case_id, client_attempt_id, answer_text,
    self_rating, result_type, duration_seconds
) VALUES (
    #{profileId}, #{request.scenarioId}, #{request.caseId}, #{request.clientAttemptId},
    #{request.answerText}, #{request.selfRating}, #{request.resultType}, #{request.durationSeconds}
)
ON CONFLICT (profile_id, client_attempt_id) DO NOTHING
RETURNING id

SELECT checksum_sha256
FROM scenario_seed_history
WHERE seed_pack = #{seedPack} AND version = #{version}

INSERT INTO scenario (
    external_key, title, summary, star_level, difficulty,
    origin_type, status, seed_pack, source_version
) VALUES (
    #{item.externalKey}, #{item.title}, #{item.summary}, #{item.starLevel}, 'HARD',
    'IMPORTED', 'ENABLED', #{pack}, #{version}
)
RETURNING id

