INSERT INTO scenario_case_solution (
    case_id, solution_id, recommendation, sort_order
) VALUES (
    #{caseId}, #{solutionId}, 'CANDIDATE', #{sortOrder}
)

INSERT INTO scenario_seed_history (
    seed_pack, version, checksum_sha256, scenario_count, case_count, solution_count
) VALUES (
    #{seedPack}, #{version}, #{checksum}, #{scenarioCount}, #{caseCount}, #{solutionCount}
)
